            //---------------------------------------------------------------------
            vypadek(typ) {
                let that = this;
                return that.dotaz("jres:26601393") //RC 26601393 : Tato volba výrazně zasahuje do dat.;;; ?????? Chcete pokračovat ??????
                    .then(() => {
                    var l_odpojeni = typ == "odpojeni";
                    var l_popisAkce = l_odpojeni ? "Zahájeno odpojení od systému NEN" : "Zahájeno napojení na systém NEN";
                    var l_vysledekAkcePlus = l_odpojeni ? "Proběhlo odpojení od systému NEN" : "Proběhlo napojení na systém NEN";
                    var l_vysledekAkceMinus = l_odpojeni ? "Odpojení od systému NEN selhalo" : "Napojení na systém NEN selhalo";
                    var l_hlasError = l_odpojeni ? "Chyba při odpojení od systému NEN" : "Chyba při napojení na systém NEN ";
                    that.notification("add", { title: l_popisAkce }, true, true);
                    let asyncTask = Gordic.Async.GTaskManager.delayedStart("Gordic.Pap.Server.GNapojeniOdpojeniNen", typ);
                    let task = undefined;
                    return asyncTask.then((asTask) => {
                        task = asTask;
                        return task.getPromise();
                    }).then((ctx) => {
                        if (ctx.result.ok) {
                            that.notification("add", { title: l_vysledekAkcePlus, state: "success" }, true, true);
                        }
                        else {
                            that.notification("add", { title: l_vysledekAkceMinus, state: "error" }, true, true);
                        }
                    }, (ctx) => {
                        this.log.error(new GError(ctx));
                        throw new GError(l_hlasError);
                    }).always(() => {
                        task?.clean();
                    });
                });
            }
