                storno(storno) {
                    var that = this;
                    var l_hlas = "";
                    var l_param = "";
                    if (!(parseDecimal(that.data.priDto.c_sum).equals(parseDecimal(0)))) {
                        that.dialogs.warning("jres:26601189", "jres:26601321"); //RC 26601321 : Případ blokuje finanční prostředky.; Operaci Storno nelze provést.
                        return;
                    }
                    var l_title = ""; //RC 26601195 : Důvod storna
                    if (that.data.priDto.s_zak == 90) {
                        l_hlas = "jres:26601197"; //RC 26601197 : Opravdu chcete provést zrušení storna případu?
                        l_param = "storno storna";
                        l_title = "jres:26601198"; //RC 26601198 : Důvod zrušení storna
                    }
                    else {
                        if (that.data.priDto.zpu_rea == 20) {
                            l_hlas = "jres:26601322"; //RC 26601322 : Případ je realizovaný v NEN. Opravdu chcete provést operaci Storno, která VZ od stavu dat v NEN odstaví?
                            l_param = "storno";
                            l_title = "jres:26601195"; //RC 26601195 : Důvod storna
                        }
                        else {
                            l_hlas = "jres:26601199"; //RC 26601199 : Opravdu chcete provést storno případu?
                            l_param = "storno";
                            l_title = "jres:26601195"; //RC 26601195 : Důvod storna
                        }
                    }
                    that.dotaz(l_hlas)
                        .then(() => {
                        var dlg = Gordic.Pap.Dialogs.GPapObecnyInput(that, { titulek: l_title, label: "jres:26601188", povinne: true, agenda: "rza", typ: "string", input: "" } //RC 26601050 : Důvod
                        , Gordic.Gin.Globals.Enums.ModOtevreni.showWindow)
                            .then(function (retVal) {
                            if (retVal != null && retVal.navrat !== null) {
                                that.isl.RzaDetail.storno({ ixs_zak: that.data.priDto.ixs_zak, duvod: retVal.navrat, akce: l_param }).get()
                                    .then(function (retVal) {
                                    if (retVal.ok) {
                                        that.isChanged = true;
                                        that.nactiData();
                                    }
                                });
                            }
                            else
                                that.dialogs.warning("jres:26601189", "jres:26601190"); //RC 26601190 : Akce nebyla provedena v důsledku nevyplnění důvodu.
                        });
                    });
                }
