                //---------------------------------------------------------------------
                function KontrolaFinOdDo(fin_od, fin_do, that) {
                    if (fin_od !== null && fin_od != 0 && fin_do !== null && fin_do != 0) {
                        if (fin_od > fin_do) {
                            that.dialogs.warning("jres:26600911", "jres:26600910"); //RC 26600911 : Upozornění
                            that.findForms("FormZuZpReal").findFields("fin_od").gfield("setValue", fin_do);
                            that.findForms("FormZuZpReal").findFields("fin_do").gfield("setValue", fin_od);
                        }
                    }
                }
                PrefabsRza.KontrolaFinOdDo = KontrolaFinOdDo;
                //---------------------------------------------------------------------
                function getRokMes(that) {
                    const ekoHlavField = Gordic.Eko.HeaderForm.Fields;
                    var date = parseDate(that.findForms(Gordic.Eko.HeaderForm.Name).findFields(ekoHlavField.DatumEvidence).gfield("getValue"));
                    //var rokMes: string = date ? date.getYear().toString() + date.getMonth().toString() : ""; 
                    var rokMes = date ? Gordic.Templates.Formatters.date(date, "yyyyMM") : "";
                    return rokMes;
                }
                PrefabsRza.getRokMes = getRokMes;
