                function vytvorRIPruRizeniFormular(option) {
                    var FormRIPruRizeni = new Gordic.Forms.Form({ name: "FormRIPruRizeni", layoutDescriptor: "L2M2S1, L-4-8-0, M-4-8-0, S-12-12-0" });
                    FormRIPruRizeni.addSection({ name: "ri1A", label: "jres:26600926" }); //RC 26600926 : Vazby a výsledek
                    if (option.rza_def_vzmrko) {
                        FormRIPruRizeni.addRow("jres:26600830").addField("gselectbox" //RC 26600830 : Druh řízení
                        , Gordic.Prefabs.Select.rzacdri(), {
                            name: "dri_pri",
                            disabled: option.readOnly,
                            model: "model.priDto.dri_pri=value.dri_pri"
                        });
                    }
                    if (option.cast) {
                        FormRIPruRizeni.addRow("jres:26600934").addField("gstringbox", {
                            name: "ixs_pri_nad",
                            disabled: true,
                            model: "model.priDto.ixs_pri_nad"
                        });
                    }
                    else {
                        FormRIPruRizeni.addRow("jres:26600934") //RC 26600934 : Nadřízená zakázka
                            .addField("gselectbox", {
                            name: "ixs_pri_nad",
                            //                    itemTemplate: "{ac_ag:trim:encode}",
                            itemTemplate: "{ixs_zak:trim:encode}",
                            disabled: option.readOnly || option.cast,
                            model: function (operation, dto, modelOptions) {
                                switch (operation) {
                                    case "apply":
                                        //     $(this).gfield("setValue", { ixs_pri: dto.pidDto["ixs_pri_nad"], ac_ag: dto.pidDto["ac_ag_pri_nad"] }, modelOptions);
                                        $(this).gfield("setInitial", { ixs_zak: dto.priDto["ixs_pri_nad"] }, modelOptions);
                                        return;
                                    case "collect":
                                        var value = $(this).gfield("getValue");
                                        if (value) {
                                            dto.priDto["ixs_pri_nad"] = value["ixs_zak"];
                                            //   dto.pidDto["ac_ag_pri_nad"] = value["ac_ag"]
                                        }
                                        else
                                            dto.priDto["ixs_pri_nad"] = "";
                                        return;
                                }
                                return "ixs_pri_nad";
                            },
                            data: function () { return option.content.isl.RzaDetail.nactiNadrizeneVZ({}).getData(); },
                            verify: function (value) {
                                var data = $(this).gfield("option", "data");
                                return data().then(function (data) {
                                    for (var i = 0; i < data.length; i++) {
                                        if (data[i].ixs_zak === value.ixs_zak) {
                                            return data[i];
                                        }
                                    }
                                    return null;
                                });
                            },
                            selector: function (options) {
                                return new Gordic.Data.Selectors.DefaultSelector({
                                    gridOpts: {},
                                    data: option.content.isl.RzaDetail.nactiNadrizeneVZ({}).getData(),
                                    gridFormat: new Gordic.Data.GridFormat()
                                        .addTextColumn({
                                        name: "ixs_zak",
                                        caption: "jres:26600928" //RC 26600928 : Identifikace AP
                                    })
                                        .addTextColumn({
                                        name: "ac_ag",
                                        caption: "jres:26600929" //RC 26600929 : Ag. číslo
                                    })
                                        .addTextColumn({
                                        name: "nazev",
                                        caption: "jres:26600930" //RC 26600930 : Název AP
                                    })
                                        .addTextColumn({
                                        name: "s_zak_txt",
                                        caption: "jres:26600931" //RC 26600931 : Stav AP
                                    })
                                        .addTextColumn({
                                        name: "ixp_den_nazev",
                                        caption: "jres:26600932" //RC 26600932 : Kniha
                                    })
                                        .addCurrencyColumn({
                                        name: "c_predp_bez",
                                        caption: "jres:26600933" //RC 26600933 : Předp. výše předmětu bez DPH
                                    }),
                                    related: $(this)
                                })
                                    .show({ title: "jres:26600934" }); //RC 26600934 : Nadřízený AP
                            }
                        });
                    }
                    FormRIPruRizeni.addRow("jres:26600831").addField("gselectbox" //RC 26600831 : Priorita případu
                    , Gordic.Prefabs.Select.rzacpri(), {
                        name: "pri_zak",
                        disabled: option.readOnly,
                        model: "model.priDto.pri_zak=value.pri_zak"
                    })
                        .addSection({ name: "ri1B", label: "jres:26600927" }) //RC 26600927 : Poznámka
                        .addRow("jres:26600927").addField("gstringbox", {
                        name: "poznamka",
                        disabled: option.readOnlyBezZR,
                        rows: 4, autoSize: true, model: "model.priDto.poznamka"
                    });
                    return FormRIPruRizeni;
                }
                PrefabsRza.vytvorRIPruRizeniFormular = vytvorRIPruRizeniFormular;
