                //---------------------------------------------------------------------
                function getText(priz_cast, s_formatem) {
                    const format = s_formatem ? "formát " : "";
                    return format + (priz_cast ? "N006/RR/VNNNNNNNN/NNN" : "N006/RR/VNNNNNNNN");
                }
                PrefabsRza.getText = getText;
