Gordic.Previews.register("rza:AP", {
    // Ověřování, zda je řádek kompletní
    canRender: function (dto) { return dto.ixs_zak != null; },
    // Samotné vykreslení náhledu
    render: function (div, dto) {
        var currentElement = $(div);
        // data jsou ready -> samotné vytvoření náhledu
        currentElement.empty().append("<h2 class='g-state-text g-state-active' style='margin: 0.5rem;'>Akviziční případ " + dto.ixs_zak + "</h2><hr style='margin: 0.5rem; opacity: 0.2;'/>");
        Gordic.Previews.displayLinkButton(div, dto);
        var tmp = $("<div class='gform--view-mode'>").appendTo(currentElement)
            .gform("setup", { layoutDescriptor: "L1M1S1, breaks-300-400" }).
            gformsection("create").gpidbar({ pid: dto.ixs_zak }).
            gformsection("create")
            .gformrow("addFieldsRow", "jres:26601264").gformtext(dto.ac_ag === null || dto.ac_ag === undefined ? "" : dto.ac_ag, "bold") //RC 26601264 : Agendové číslo
            .gformrow("addFieldsRow", "jres:26601265").gformtext(dto.ac === null || dto.ac === undefined ? "" : dto.ac, "bold") //RC 26601265 : Evidenční číslo
            .gformrow("addFieldsRow", "jres:26601266").gformtext(dto.nazev === null || dto.nazev === undefined ? "" : dto.nazev, "bold") //RC 26601266 : Název
            .gformrow("addFieldsRow", "jres:26601169").gformtext(dto.hlav_pred_pop === null || dto.hlav_pred_pop === undefined ? "" : dto.hlav_pred_pop, "bold"); //RC 26601169 : Popis předmětu
        //.gformrow("addFieldsRow", "jres:26600065").gformtext(dto.s_sdg_txt === null || dto.s_sdg_txt === undefined ? "" : dto.s_sdg_txt, "bold") //RC 26600065 : Stav vyhlášení
        //.gformrow("addFieldsRow", "jres:26600069").gformtext(dto.dat_zdg === null ? "" : Gordic.Templates.Formatters.date(dto.dat_zdg), "bold")//RC 26600069 : Datum zrušení
        //.gformrow("addFieldsRow", "jres:26600596").gformtext(dto.ixp_den_evzspac === null || dto.ixp_den_evzspac === undefined ? "" : dto.ixp_den_evzspac, "bold") //RC 26600596 : Kniha (AC)
        currentElement.resize().find(".gform-section").children("label").first().addClass("g-state-text g-state-active");
    }
});
